- Purchase accounting / acquisition integration experience.
- Power BI for management reporting.$seed$, $seed${"hours_per_week":null,"industries":["manufacturing"],"min_overlap_hours":null,"min_years_experience":5,"must_haves":["CPA","5+ years of progressive accounting experience, at least 3 as a Controller or Assistant Controller in a manufacturing business","Experience with Microsoft Dynamics 365 (Business Central or Finance)","Standard costing and inventory valuation under US GAAP","Mountain time; on-site in Denver 3 days a week"],"nice_to_haves":["CMA","Purchase accounting / acquisition integration experience","Power BI for management reporting"],"other_industries":[],"other_preferred_certifications":[],"other_preferred_software":[],"other_required_certifications":[],"other_required_software":[],"preferred_certifications":["cma"],"preferred_software":["power_bi"],"required_certifications":["cpa_us"],"required_qualifications":[{"accept_equivalents":true,"canonical":"cpa_us","equivalents_stated":false,"name_as_written":"CPA","quote":"CPA"}],"required_software":["microsoft_dynamics_365"],"timezone":"America/Denver","title":"Controller"}$seed$::jsonb || jsonb_build_object('starts_on', (CURRENT_DATE + 45)::text), $seed$["CPA","5+ years of progressive accounting experience, at least 3 as a Controller or Assistant Controller in a manufacturing business","Experience with Microsoft Dynamics 365 (Business Central or Finance)","Standard costing and inventory valuation under US GAAP","Mountain time; on-site in Denver 3 days a week"]$seed$::jsonb, $seed$["CMA","Purchase accounting / acquisition integration experience","Power BI for management reporting"]$seed$::jsonb, '{cpa_us}', '{microsoft_dynamics_365}', 5, $seed$America/Denver$seed$, NULL, 40, CURRENT_DATE + 45, $seed$open$seed$),
